-- Shared memory schema (Cloudflare D1 / SQLite). Safe to run more than once.

-- Memory "files": /profile.md, /preferences.md, /areas/<client>.md, /people/<name>.md, /topics/<topic>.md
CREATE TABLE IF NOT EXISTS memories (
  path        TEXT PRIMARY KEY,
  content     TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  updated_at  TEXT NOT NULL,
  updated_by  TEXT
);

-- One row per conversation / Claude Code session.
-- summary    = short summary (written by Claude via session_log, or auto-generated by the hook)
-- transcript = the messages of the session (written automatically by the Claude Code hook)
CREATE TABLE IF NOT EXISTS sessions (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id  TEXT NOT NULL UNIQUE,
  surface     TEXT NOT NULL,
  project     TEXT,
  title       TEXT,
  summary     TEXT NOT NULL DEFAULT '',
  transcript  TEXT,
  source      TEXT NOT NULL DEFAULT 'claude',
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_sessions_updated ON sessions(updated_at);
CREATE INDEX IF NOT EXISTS idx_sessions_project ON sessions(project);
